<?php require_once __DIR__.'/includes/functions.php';$u=require_login();$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$name=trim((string)($_POST['name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$password=(string)($_POST['password']??'');if(!valid_name($name))$errors[]='Name must be 2–100 characters.';if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($email)>190)$errors[]='Enter a valid email.';if($password!==''&&!valid_password($password))$errors[]='New password must be 8–72 characters.';if(!$errors){try{$avatar=avatar_upload('avatar',$u['avatar']);$hash=$password!==''?password_hash($password,PASSWORD_DEFAULT):null;$stmt=db()->prepare('UPDATE users SET name=?,email=?,avatar=?,password_hash=COALESCE(?,password_hash) WHERE id=?');$stmt->execute([$name,$email,$avatar,$hash,$u['id']]);flash('success','Profile updated successfully.');redirect('profile.php');}catch(PDOException $ex){if($ex->getCode()==='23000')$errors[]='That email is already taken.';else throw $ex;}catch(RuntimeException $ex){$errors[]=$ex->getMessage();}}}page_start('Edit profile');?><section class="page-head"><span class="eyebrow">ACCOUNT SETTINGS</span><h1>Edit your profile</h1><p class="muted">Your changes are saved securely.</p></section><div class="panel narrow"><?php foreach($errors as $err):?><div class="alert error"><?=e($err)?></div><?php endforeach;?><div class="avatar-row"><?php if($u['avatar']):?><img class="avatar" alt="Profile photo" src="<?=e(url('uploads/'.$u['avatar']))?>"><?php else:?><span class="avatar placeholder"><?=e(strtoupper(mb_substr($u['name'],0,1)))?></span><?php endif;?><div><h2><?=e($u['name'])?></h2><p class="muted"><?=e(ucfirst($u['role']))?> account</p></div></div><form method="post" enctype="multipart/form-data" class="stack"><?=csrf_field()?><label>Full name<input name="name" maxlength="100" required value="<?=e($u['name'])?>"></label><label>Email<input type="email" name="email" required value="<?=e($u['email'])?>"></label><label>New password <small>(leave blank to keep current)</small><input type="password" name="password" minlength="8" maxlength="72" autocomplete="new-password"></label><label>Profile picture <small>(JPG, PNG, WebP · max 2 MB)</small><input type="file" name="avatar" accept="image/jpeg,image/png,image/webp"></label><button class="button" type="submit">Save changes</button></form></div><?php page_end(); ?>
